import java.util.*;
import org.apache.hc.client5.http.HttpRoute;
import java.util.concurrent.ConcurrentSkipListSet;

// Thread does not implement equals/hashCode nor compareTo
class Foo {
    Set<String> strSet = new HashSet<>();
    Set<Thread> threadFieldSet = new HashSet<>(); // bad 8
    Thread t = new Thread();
    List<String> strList = new ArrayList<>();
    List<Thread> tList = new ArrayList<>();
    Set<HttpRoute> routeSet = new HashSet<>(); // bad 12, HttpRoute not comparable
    Set tSet = new HashSet();
    Set<HttpRoute> fieldRouteSetNonComp = new TreeSet<>(); // bad 14, HttpRoute not comparable and no explicit comparator
    Set<HttpRoute> fieldRouteSetConc = new ConcurrentSkipListSet<>(); // bad 15: HttpRoute not comparabl with explicit comparator

    void byElemBad(Set<Thread> threadParamSet) { // probably bad, but cannot tell actual Set implementation and construction
        Set<Thread> localThreadFieldSet = new HashSet<>(); // bad 18

        threadParamSet.retainAll(tList);
        localThreadFieldSet.containsAll(tList);

        threadFieldSet.contains(t);

        Set<Thread> threadLocalSet = new HashSet<>(); // bad 25
        threadLocalSet.containsAll(tList);

        Set<HttpRoute> routeLocalSet = new HashSet<>(); // bad 28
        routeLocalSet.removeAll(routeSet);
    }

    void otherCasesGood(Set<Thread> threadParamSet2) { // probably bad, but cannot tell actual Set implementation and construction
        strSet.contains("bla");
        strSet.containsAll(strList);
        strSet.retainAll(strList);
        strSet.removeAll(strList);
        threadParamSet2.remove(t);
        threadParamSet2.iterator().next();
        tSet.remove(t);
        HttpRoute firstRoute = routeSet.iterator().next();
        routeSet.contains(firstRoute);
        fieldRouteSetNonComp.containsAll(routeSet);
        fieldRouteSetConc.containsAll(routeSet);
    }
}

