import java.util.Comparator;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.ConcurrentSkipListSet;

public class Foo {

    public static final Comparator<Class> CLASS_NAME_COMPARATOR = Comparator.comparing(Class::getName);
    private static final Set<Class> allClassesConc = new ConcurrentSkipListSet<>(CLASS_NAME_COMPARATOR); // good: with explicit comparator

    public void bar() {
        final Set<Class> types = new TreeSet<>(CLASS_NAME_COMPARATOR); // good: with explicit comparator
        foo(types);
    }

    public void foo(Set<Class> types) { // <--- false positive, has constructor with comparator
        types.contains(String.class);
        allClassesConc.contains(String.class);
    }

}
